CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', invite_code text NOT NULL UNIQUE DEFAULT upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)), referrer_id uuid REFERENCES public.profiles(id), registered boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated; GRANT UPDATE(display_name) ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY update_name ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE TABLE public.wallets (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, balance_cents bigint NOT NULL DEFAULT 0 CHECK(balance_cents>=0));
GRANT SELECT ON public.wallets TO authenticated; GRANT ALL ON public.wallets TO service_role;
ALTER TABLE public.wallets ENABLE ROW LEVEL SECURITY; CREATE POLICY own_wallet ON public.wallets FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.plans (id text PRIMARY KEY, name text NOT NULL, destination text NOT NULL, price_cents bigint NOT NULL CHECK(price_cents>0), category text NOT NULL);
GRANT SELECT ON public.plans TO anon,authenticated; GRANT ALL ON public.plans TO service_role;
ALTER TABLE public.plans ENABLE ROW LEVEL SECURITY; CREATE POLICY catalog ON public.plans FOR SELECT TO anon,authenticated USING(true);
INSERT INTO public.plans VALUES ('explorador','Explorador','Maragogi, Alagoas',10000,'Essencial'),('viajante','Viajante','Porto de Galinhas, Pernambuco',25000,'Mais escolhido'),('pioneiro','Pioneiro','Praia do Forte, Bahia',50000,'Premium');
CREATE TABLE public.orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), plan_id text NOT NULL REFERENCES public.plans(id), price_cents bigint NOT NULL CHECK(price_cents>0), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid')), created_at timestamptz NOT NULL DEFAULT now(), paid_at timestamptz);
GRANT SELECT ON public.orders TO authenticated; GRANT ALL ON public.orders TO service_role;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY; CREATE POLICY own_orders ON public.orders FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), order_id uuid UNIQUE REFERENCES public.orders(id), kind text NOT NULL CHECK(kind IN ('welcome','purchase','referral','scenario')), amount_cents bigint NOT NULL, description text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.transactions TO authenticated; GRANT ALL ON public.transactions TO service_role;
ALTER TABLE public.transactions ENABLE ROW LEVEL SECURITY; CREATE POLICY own_transactions ON public.transactions FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE INDEX profile_parent ON public.profiles(referrer_id); CREATE INDEX transaction_owner ON public.transactions(user_id,created_at); CREATE INDEX orders_owner ON public.orders(user_id);
CREATE FUNCTION public.finish_registration(p_name text,p_inviter text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE parent_id uuid; me uuid:=auth.uid(); done boolean; code text:=upper(trim(p_inviter)); BEGIN IF me IS NULL THEN RAISE EXCEPTION 'Entre na sua conta.'; END IF; IF length(trim(p_name))<2 THEN RAISE EXCEPTION 'Informe seu nome.'; END IF; SELECT registered INTO done FROM public.profiles WHERE id=me FOR UPDATE; IF done THEN RETURN; END IF; IF code='' THEN RAISE EXCEPTION 'Indicador obrigatório.'; END IF; IF code<>'SAFRAROTA' THEN SELECT id INTO parent_id FROM public.profiles WHERE invite_code=code AND registered; IF parent_id IS NULL OR parent_id=me THEN RAISE EXCEPTION 'Indicador inválido.'; END IF; END IF; UPDATE public.profiles SET display_name=trim(p_name),referrer_id=parent_id,registered=true WHERE id=me; INSERT INTO public.wallets(user_id,balance_cents) VALUES(me,100000); INSERT INTO public.transactions(user_id,kind,amount_cents,description) VALUES(me,'welcome',100000,'Crédito inicial de simulação'); END $$;
REVOKE ALL ON FUNCTION public.finish_registration(text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.finish_registration(text,text) TO authenticated;
CREATE FUNCTION public.handle_safra_signup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE parent_id uuid; code text:=upper(trim(coalesce(new.raw_user_meta_data->>'inviter',''))); person text:=trim(coalesce(new.raw_user_meta_data->>'display_name','')); BEGIN IF code<>'' AND code<>'SAFRAROTA' THEN SELECT id INTO parent_id FROM public.profiles WHERE invite_code=code AND registered; IF parent_id IS NULL THEN RAISE EXCEPTION 'Indicador inválido.'; END IF; END IF; INSERT INTO public.profiles(id,display_name,referrer_id,registered) VALUES(new.id,person,parent_id,code<>'' AND length(person)>=2); IF code<>'' AND length(person)>=2 THEN INSERT INTO public.wallets(user_id,balance_cents) VALUES(new.id,100000); INSERT INTO public.transactions(user_id,kind,amount_cents,description) VALUES(new.id,'welcome',100000,'Crédito inicial de simulação'); END IF; RETURN new; END $$;
REVOKE ALL ON FUNCTION public.handle_safra_signup() FROM PUBLIC;
CREATE TRIGGER safra_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_safra_signup();
CREATE FUNCTION public.create_virtual_order(p_plan text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; cost bigint; BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND registered) THEN RAISE EXCEPTION 'Complete seu cadastro.'; END IF; SELECT price_cents INTO cost FROM public.plans WHERE id=p_plan; IF cost IS NULL THEN RAISE EXCEPTION 'Plano inválido.'; END IF; INSERT INTO public.orders(user_id,plan_id,price_cents) VALUES(auth.uid(),p_plan,cost) RETURNING id INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.create_virtual_order(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_virtual_order(text) TO authenticated;
CREATE FUNCTION public.pay_virtual_order(p_order uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE item public.orders; bal bigint; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre na sua conta.'; END IF; SELECT * INTO item FROM public.orders WHERE id=p_order AND user_id=auth.uid() FOR UPDATE; IF item.id IS NULL THEN RAISE EXCEPTION 'Pedido não encontrado.'; END IF; IF item.status='paid' THEN RETURN; END IF; SELECT balance_cents INTO bal FROM public.wallets WHERE user_id=auth.uid() FOR UPDATE; IF bal IS NULL OR bal<item.price_cents THEN RAISE EXCEPTION 'Saldo virtual insuficiente.'; END IF; UPDATE public.wallets SET balance_cents=balance_cents-item.price_cents WHERE user_id=auth.uid(); INSERT INTO public.transactions(user_id,order_id,kind,amount_cents,description) VALUES(auth.uid(),item.id,'purchase',-item.price_cents,'Adesão virtual · '||item.plan_id); UPDATE public.orders SET status='paid',paid_at=now() WHERE id=item.id; END $$;
REVOKE ALL ON FUNCTION public.pay_virtual_order(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.pay_virtual_order(uuid) TO authenticated;
CREATE FUNCTION public.my_referral_tree() RETURNS TABLE(id uuid,display_name text,invite_code text,referrer_id uuid,level integer,created_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH RECURSIVE tree AS (SELECT p.id,p.display_name,p.invite_code,p.referrer_id,1 AS level,p.created_at FROM public.profiles p WHERE p.referrer_id=auth.uid() AND p.registered UNION ALL SELECT p.id,p.display_name,p.invite_code,p.referrer_id,t.level+1,p.created_at FROM public.profiles p JOIN tree t ON p.referrer_id=t.id WHERE t.level<3 AND p.registered) SELECT * FROM tree $$;
REVOKE ALL ON FUNCTION public.my_referral_tree() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.my_referral_tree() TO authenticated;